pub(super) fn project(projection:&mut Projection<'_,'_>,id:i64,v:&DwgViewportEntity)->Result<(),ValueError>{
    let render=match v.render_mode{DwgViewportRenderMode::Optimized2d=>"optimized2d",DwgViewportRenderMode::Wireframe=>"wireframe",DwgViewportRenderMode::HiddenLine=>"hidden_line",DwgViewportRenderMode::FlatShaded=>"flat_shaded",DwgViewportRenderMode::GouraudShaded=>"gouraud_shaded",DwgViewportRenderMode::FlatShadedWithWireframe=>"flat_shaded_with_wireframe",DwgViewportRenderMode::GouraudShadedWithWireframe=>"gouraud_shaded_with_wireframe"};
    let ortho=match v.orthographic_view{DwgOrthographicView::None=>"none",DwgOrthographicView::Top=>"top",DwgOrthographicView::Bottom=>"bottom",DwgOrthographicView::Front=>"front",DwgOrthographicView::Back=>"back",DwgOrthographicView::Left=>"left",DwgOrthographicView::Right=>"right"};
    let shade=match v.shade_plot_mode{DwgShadePlotMode::AsDisplayed=>"as_displayed",DwgShadePlotMode::Wireframe=>"wireframe",DwgShadePlotMode::Hidden=>"hidden",DwgShadePlotMode::Rendered=>"rendered"};
    let lighting=match v.default_lighting_type{DwgDefaultLightingType::OneDistantLight=>"one_distant_light",DwgDefaultLightingType::TwoDistantLights=>"two_distant_lights"};
    let clip=optional_words(v.clip_boundary_handle);let named=optional_words(v.named_ucs_handle);let base=optional_words(v.base_ucs_handle);let background=optional_words(v.background_handle);let visual=optional_words(v.visual_style_handle);let shade_handle=optional_words(v.shade_plot_handle);let sun=optional_words(v.sun_handle);
    projection.insert_key("dwg_viewport_entity",id,&[R(v.width),R(v.height),R(v.twist_angle),R(v.view_height),R(v.lens_length),R(v.front_clip),R(v.back_clip),R(v.snap_angle),I(i64::from(v.circle_zoom_percent)),I(i64::from(v.grid_major)),T(&v.style_sheet),T(render),I(i64::from(v.ucs_at_origin)),I(i64::from(v.ucs_per_viewport)),R(v.ucs_elevation),T(ortho),T(shade),I(i64::from(v.use_default_lights)),T(lighting),R(v.brightness),R(v.contrast),clip[0],clip[1],named[0],named[1],base[0],base[1],background[0],background[1],visual[0],visual[1],shade_handle[0],shade_handle[1],sun[0],sun[1]])?;
    for(table,values)in [("dwg_entity_center_coordinate",&v.center),("dwg_viewport_view_target_coordinate",&v.view_target),("dwg_viewport_view_direction_coordinate",&v.view_direction),("dwg_viewport_view_center_coordinate",&v.view_center),("dwg_viewport_snap_base_coordinate",&v.snap_base),("dwg_viewport_snap_unit_coordinate",&v.snap_unit),("dwg_viewport_grid_unit_coordinate",&v.grid_unit),("dwg_viewport_ucs_origin_coordinate",&v.ucs_origin),("dwg_viewport_ucs_x_axis_coordinate",&v.ucs_x_axis),("dwg_viewport_ucs_y_axis_coordinate",&v.ucs_y_axis)]{coordinates(projection,table,id,values)?;}
    handles(projection,"dwg_viewport_frozen_layer_handle",id,&v.frozen_layer_handles)?;
    for(index,value)in v.status.iter().enumerate(){projection.insert("dwg_viewport_status_flag",&[I(id),I(ordinal(index)?),T(flag(*value))])?;}
    color::project(projection,"dwg_viewport_ambient_color",id,&v.ambient_color)
}
